// ===================== ESCUTA DE GRUPOS (Clube Kotas e outros) =====================
const corpo = $('Webhook').first().json.body || {};
let d = corpo.data;
if (Array.isArray(d)) d = d[0];
if (!d || !d.key) return [];
const evento = String(corpo.event || '').toLowerCase().replace('_', '.');
if (evento && evento !== 'messages.upsert') return [];
if (d.key.fromMe) return [];

const AJ = await lerAjustes();
const fontes = (Array.isArray(AJ.fontes) ? AJ.fontes : []).map(f => f.jid);
const jid = d.key.remoteJid;
if (!fontes.includes(jid)) return [];
const nomeFonte = ((AJ.fontes || []).find(f => f.jid === jid) || {}).nome || 'grupo';

// Desembrulha mensagens temporárias, de visualização única, editadas etc. (o grupo do Kotas usa mensagens temporárias)
let m = d.message || {};
for (let i = 0; i < 5; i++) {
  const dentro = (m.ephemeralMessage || m.viewOnceMessage || m.viewOnceMessageV2 || m.viewOnceMessageV2Extension
    || m.documentWithCaptionMessage || m.editedMessage || {}).message;
  if (!dentro) break;
  m = dentro;
}
if (m.protocolMessage && m.protocolMessage.editedMessage) m = m.protocolMessage.editedMessage;
const texto = String(
  m.conversation ||
  (m.extendedTextMessage && m.extendedTextMessage.text) ||
  (m.imageMessage && m.imageMessage.caption) ||
  (m.videoMessage && m.videoMessage.caption) ||
  (m.documentMessage && m.documentMessage.caption) || ''
).trim();
if (!texto) return [];

// Links de convite, redes sociais e o site do próprio grupo-fonte não interessam
// (links encurtados do próprio Kotas NÃO são ignorados: eles podem levar ao produto; se não levarem, o robô descarta sozinho)
const IGNORAR = ['chat.whatsapp.com', 'wa.me', 't.me', 'instagram.com', 'tiktok.com', 'youtube.com', 'x.com', 'threads.com', 'facebook.com'];
const urls = (texto.match(/https?:\/\/[^\s<>"]+/g) || [])
  .map(u => u.replace(/[).,;!*_~]+$/, ''))
  .filter(u => hostDe(u) && !IGNORAR.some(dom => hostDe(u) === dom || hostDe(u).endsWith('.' + dom)));
if (!urls.length) return [];

try {
  let achado = null, linkOriginal = null;
  for (const u of urls) {
    const r = await resolver(u);
    const id = identificar(r.url, r.html);
    if (id) { achado = id; linkOriginal = u; break; }
  }
  if (!achado) return [];
  // Loja ainda não configurada: ignora em silêncio (não ocupa a fila)
  if (achado.loja === 'amazon' && !cfg.amazon_tag) return [];
  if (achado.loja === 'shopee' && !(cfg.shopee_app_id && cfg.shopee_secret)) return [];

  // Preço e cupom escritos no post
  const NUM = '(\\d{1,3}(?:\\.\\d{3})+(?:,\\d{1,2})?|\\d+(?:,\\d{1,2})?)';
  const pega = re => { const x = texto.match(re); return x ? num(x[1]) : null; };
  let precoDe = pega(new RegExp('^[^\\w\\n]*de\\b[:\\s]*(?:R\\$\\s*)?' + NUM, 'im'));
  let precoPor = pega(new RegExp('^[^\\w\\n]*por\\b[:\\s]*(?:R\\$\\s*)?' + NUM, 'im')) || pega(new RegExp('R\\$\\s*' + NUM, 'i'));
  if (precoDe && precoPor && precoDe <= precoPor) precoDe = null;
  const cupom = ((texto.match(/cupo[mn]\b[:\s]+([A-Z0-9][A-Z0-9_-]{2,})/i) || [])[1] || '').toUpperCase() || null;

  const reg = await sb('POST', 'rpc/registrar_captura', { p: {
    fonte_jid: jid, fonte_msg_id: d.key.id, texto_original: texto.slice(0, 2000),
    loja: achado.loja, produto_key: achado.key || achado.produto_url, produto_url: achado.produto_url,
    link_original: linkOriginal, preco_de: precoDe, preco_por: precoPor, cupom
  } });
  if (!reg || !reg.novo) return [{ json: { ignorada: true, motivo: reg && reg.motivo } }];

  const precoLinha = [precoDe ? `De ${brl(precoDe)}` : null, precoPor ? `Por ${brl(precoPor)}` : null].filter(Boolean).join(' · ');
  const resumo = texto.split('\n').map(s => s.trim()).filter(s => s && !/https?:\/\//.test(s) && !/encaminhe|participar do grupo/i.test(s)).slice(0, 5).join('\n');

  // Amazon e Shopee: o link de afiliado sai sozinho, então já vai direto para a prévia
  if (achado.loja !== 'mercadolivre') {
    const fmt = v => Number(v).toFixed(2).replace('.', ',');
    const txt = [achado.produto_url,
      precoDe && precoPor ? `de ${fmt(precoDe)} por ${fmt(precoPor)}` : (precoPor ? fmt(precoPor) : ''),
      cupom ? `cupom ${cupom}` : ''].filter(Boolean).join('\n');
    try {
      const dados = await dadosDoTexto(txt, 'escuta_grupos');
      const { oferta, aviso } = await criarRascunho(AJ, dados, { id: reg.id });
      await enviarPrevia(AJ, oferta, `Capturada em: ${nomeFonte}${aviso ? '\n' + aviso : ''}`);
      return [{ json: { capturada: true, previa: true, id: reg.id } }];
    } catch (e) {
      await avisar(AJ, `🛒 Capturada em ${nomeFonte} (${LOJAS[achado.loja]}), mas não consegui montar a prévia:\n${erroTxt(e)}\n\nProduto: ${achado.produto_url}\nResponda esta mensagem com o link e o preço para tentar de novo.`);
      return [];
    }
  }

  // Mercado Livre: precisa do seu meli.la
  const linhas = [
    `🛒 Capturada em ${nomeFonte} · Mercado Livre`,
    '',
    resumo,
    '',
    precoLinha ? `Preço no post: ${precoLinha}` : 'Preço no post: não identificado',
    cupom ? `Cupom: ${cupom}` : null,
    achado.key ? null : '⚠️ Não achei o produto exato. Abra o link e confira.',
    '',
    `Produto: ${achado.produto_url}`,
    '',
    '↩️ RESPONDA esta mensagem com o seu link meli.la. Se o preço mudou, mande junto (ex.: 599,90).'
  ].filter(l => l !== null);
  const enviado = await avisar(AJ, linhas.join('\n'), {
    disable_web_page_preview: false,
    reply_markup: { inline_keyboard: [[{ text: '🗑️ Ignorar', callback_data: 'ign:' + reg.id }]] }
  });
  const msgId = enviado && enviado.result && enviado.result.message_id;
  if (msgId) await sb('PATCH', `capturas?id=eq.${reg.id}`, { tg_message_id: msgId }, 'return=minimal');
  return [{ json: { capturada: true, id: reg.id, loja: achado.loja } }];
} catch (e) {
  await avisar(AJ, '❌ Erro na escuta de grupos: ' + erroTxt(e));
  return [];
}
